1	#!/usr/bin/env python3
2	"""babel_code_goat.py — test-harness translation engine and runner.
3	
4	Requires Python 3.9+.
5	
6	Commands:
7	  generate <tests_dir> --entrypoint <name> --lang <python|javascript|typescript>
8	  test     <solution>  <tests_dir> --lang <python|javascript|typescript>
9	"""
10	from __future__ import annotations
11	
12	import argparse
13	import ast
14	import json
15	import os
16	import re
17	import subprocess
18	import sys
19	import tempfile
20	from dataclasses import dataclass, field
21	from pathlib import Path
22	from typing import Any, Literal
23	
24	
25	# ---------------------------------------------------------------------------
26	# IR
27	# ---------------------------------------------------------------------------
28	
29	@dataclass
30	class TestCase:
31	    id: str                          # temporary: raw line number; final: "tests.py:<n>[#k]"
32	    kind: Literal["eq", "ne", "truthy", "falsy", "raises"]
33	    args: list[Any]
34	    expected: Any = None
35	    expect_stdout: str | None = None
36	    expect_stderr: str | None = None
37	
38	
39	# ---------------------------------------------------------------------------
40	# Value helpers
41	# ---------------------------------------------------------------------------
42	
43	def _ast_to_value(node: ast.expr) -> Any:
44	    """Evaluate a constant-valued AST node to a Python value."""
45	    if isinstance(node, ast.Constant):
46	        return node.value
47	    if isinstance(node, ast.List):
48	        return [_ast_to_value(e) for e in node.elts]
49	    if isinstance(node, ast.Tuple):
50	        return [_ast_to_value(e) for e in node.elts]  # tuple → list (no tuple in JSON)
51	    if isinstance(node, ast.Dict):
52	        return {_ast_to_value(k): _ast_to_value(v) for k, v in zip(node.keys, node.values)}
53	    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.USub, ast.UAdd)):
54	        v = _ast_to_value(node.operand)
55	        return -v if isinstance(node.op, ast.USub) else v
56	    raise ValueError(f"Unsupported value in tests.py: {ast.dump(node)}")
57	
58	
59	def _to_json_value(v: Any) -> Any:
60	    """Recursively normalise to JSON-safe form (tuple → list)."""
61	    if isinstance(v, (list, tuple)):
62	        return [_to_json_value(x) for x in v]
63	    if isinstance(v, dict):
64	        return {k: _to_json_value(vv) for k, vv in v.items()}
65	    return v
66	
67	
68	# ---------------------------------------------------------------------------
69	# Parser
70	# ---------------------------------------------------------------------------
71	
72	_ANNO_RE = re.compile(r"#\s*expect_(stdout|stderr):\s*(.+)")
73	
74	
75	def parse_tests(source: str, entrypoint: str) -> list[TestCase]:
76	    """Parse tests.py source and return a list of TestCase objects."""
77	    tree = ast.parse(source)
78	    lines = source.splitlines()
79	    raw: list[TestCase] = []
80	    _collect_stmts(tree.body, lines, entrypoint, raw)
81	
82	    # Assign proper IDs: "tests.py:<line>" or "tests.py:<line>#N" for collisions.
83	    # tc.id is stored as str(lineno) initially.
84	    line_counts: dict[int, int] = {}
85	    for tc in raw:
86	        n = int(tc.id)
87	        line_counts[n] = line_counts.get(n, 0) + 1
88	    line_seen: dict[int, int] = {}
89	    for tc in raw:
90	        n = int(tc.id)
91	        if line_counts[n] == 1:
92	            tc.id = f"tests.py:{n}"
93	        else:
94	            idx = line_seen.get(n, 0)
95	            tc.id = f"tests.py:{n}#{idx}"
96	            line_seen[n] = idx + 1
97	    return raw
98	
99	
100	def _collect_stmts(
101	    stmts: list[ast.stmt], lines: list[str], ep: str, out: list[TestCase]
102	) -> None:
103	    for stmt in stmts:
104	        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):
105	            _collect_stmts(stmt.body, lines, ep, out)
106	        elif isinstance(stmt, ast.ClassDef):
107	            _collect_stmts(stmt.body, lines, ep, out)
108	        elif isinstance(stmt, ast.If):
109	            _collect_stmts(stmt.body + stmt.orelse, lines, ep, out)
110	        elif isinstance(stmt, (ast.For, ast.While)):
111	            _collect_stmts(stmt.body + stmt.orelse, lines, ep, out)
112	        elif isinstance(stmt, ast.With):
113	            _collect_stmts(stmt.body, lines, ep, out)
114	        elif isinstance(stmt, ast.Try):
115	            tc = _match_raises(stmt, ep)
116	            if tc is not None:
117	                _attach_annotations(tc, stmt.lineno, lines)
118	                out.append(tc)
119	            else:
120	                _collect_stmts(stmt.body, lines, ep, out)
121	                for h in stmt.handlers:
122	                    _collect_stmts(h.body, lines, ep, out)
123	        elif isinstance(stmt, ast.Assert):
124	            tc = _match_assert(stmt, ep)
125	            if tc is not None:
126	                _attach_annotations(tc, stmt.lineno, lines)
127	                out.append(tc)
128	
129	
130	def _is_ep_call(node: ast.expr, ep: str) -> bool:
131	    return (
132	        isinstance(node, ast.Call)
133	        and isinstance(node.func, ast.Name)
134	        and node.func.id == ep
135	    )
136	
137	
138	def _match_raises(node: ast.Try, ep: str) -> TestCase | None:
139	    """Match: try: EP(args); assert False \\n except Exception: pass"""
140	    if len(node.body) != 2 or len(node.handlers) != 1:
141	        return None
142	    h = node.handlers[0]
143	    if not (isinstance(h.type, ast.Name) and h.type.id == "Exception"):
144	        return None
145	    if not (len(h.body) == 1 and isinstance(h.body[0], ast.Pass)):
146	        return None
147	    s0, s1 = node.body
148	    if not (isinstance(s0, ast.Expr) and _is_ep_call(s0.value, ep)):
149	        return None
150	    if not (
151	        isinstance(s1, ast.Assert)
152	        and isinstance(s1.test, ast.Constant)
153	        and s1.test.value is False
154	    ):
155	        return None
156	    args = [_ast_to_value(a) for a in s0.value.args]
157	    return TestCase(id=str(node.lineno), kind="raises", args=args)
158	
159	
160	def _match_assert(node: ast.Assert, ep: str) -> TestCase | None:
161	    test = node.test
162	    # assert EP(args) == expected   or   assert EP(args) != expected
163	    if (
164	        isinstance(test, ast.Compare)
165	        and len(test.ops) == 1
166	        and len(test.comparators) == 1
167	        and _is_ep_call(test.left, ep)
168	    ):
169	        args = [_ast_to_value(a) for a in test.left.args]
170	        exp = _ast_to_value(test.comparators[0])
171	        if isinstance(test.ops[0], ast.Eq):
172	            return TestCase(id=str(node.lineno), kind="eq", args=args, expected=exp)
173	        if isinstance(test.ops[0], ast.NotEq):
174	            return TestCase(id=str(node.lineno), kind="ne", args=args, expected=exp)
175	    # assert EP(args)
176	    if _is_ep_call(test, ep):
177	        return TestCase(
178	            id=str(node.lineno), kind="truthy",
179	            args=[_ast_to_value(a) for a in test.args],
180	        )
181	    # assert not EP(args)
182	    if (
183	        isinstance(test, ast.UnaryOp)
184	        and isinstance(test.op, ast.Not)
185	        and _is_ep_call(test.operand, ep)
186	    ):
187	        return TestCase(
188	            id=str(node.lineno), kind="falsy",
189	            args=[_ast_to_value(a) for a in test.operand.args],
190	        )
191	    return None
192	
193	
194	def _attach_annotations(tc: TestCase, lineno: int, lines: list[str]) -> None:
195	    """Scan backwards from the line before lineno for expect_stdout/stderr annotations."""
196	    i = lineno - 2  # 0-indexed line immediately before the test
197	    while i >= 0:
198	        m = _ANNO_RE.match(lines[i].strip())
199	        if not m:
200	            break
201	        kind, raw_val = m.group(1), m.group(2).strip()
202	        parsed: str = ast.literal_eval(raw_val)
203	        if kind == "stdout" and tc.expect_stdout is None:
204	            tc.expect_stdout = parsed
205	        elif kind == "stderr" and tc.expect_stderr is None:
206	            tc.expect_stderr = parsed
207	        i -= 1
208	
209	
210	# ---------------------------------------------------------------------------
211	# Code generators
212	# ---------------------------------------------------------------------------
213	
214	def emit_python(cases: list[TestCase], entrypoint: str) -> str:
215	    cases_data = [
216	        [tc.id, tc.kind, _to_json_value(tc.args), _to_json_value(tc.expected),
217	         tc.expect_stdout, tc.expect_stderr]
218	        for tc in cases
219	    ]
220	    cases_repr = repr(json.dumps(cases_data))
221	    ep_repr = json.dumps(entrypoint)
222	
223	    return f"""\
224	#!/usr/bin/env python3
225	import sys, json, os, io, contextlib, importlib.util
226	
227	ENTRYPOINT = {ep_repr}
228	CASES = json.loads({cases_repr})
229	
230	def _deep_eq(a, b):
231	    if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
232	        return len(a) == len(b) and all(_deep_eq(x, y) for x, y in zip(a, b))
233	    if isinstance(a, dict) and isinstance(b, dict):
234	        return set(a) == set(b) and all(_deep_eq(a[k], b[k]) for k in a)
235	    return a == b
236	
237	def _load_fn(sol_path, name):
238	    spec = importlib.util.spec_from_file_location("_sol", sol_path)
239	    mod = importlib.util.module_from_spec(spec)
240	    spec.loader.exec_module(mod)
241	    obj = getattr(mod, name)
242	    if isinstance(obj, type):
243	        return getattr(obj(), name)
244	    return obj
245	
246	def _run():
247	    sol_path = sys.argv[1]
248	    results_path = os.environ["_BCG_RESULTS_FILE"]
249	    try:
250	        fn = _load_fn(sol_path, ENTRYPOINT)
251	    except Exception:
252	        with open(results_path, "w") as f:
253	            json.dump({{"passed": [], "failed": [c[0] for c in CASES]}}, f)
254	        return
255	    passed, failed = [], []
256	    for tid, kind, args, expected, exp_out, exp_err in CASES:
257	        try:
258	            if kind == "raises":
259	                try:
260	                    fn(*args)
261	                    failed.append(tid)
262	                except Exception:
263	                    passed.append(tid)
264	                continue
265	            out_buf, err_buf = io.StringIO(), io.StringIO()
266	            with contextlib.redirect_stdout(out_buf), contextlib.redirect_stderr(err_buf):
267	                result = fn(*args)
268	            ok = True
269	            if kind == "eq":
270	                ok = _deep_eq(result, expected)
271	            elif kind == "ne":
272	                ok = not _deep_eq(result, expected)
273	            elif kind == "truthy":
274	                ok = bool(result)
275	            elif kind == "falsy":
276	                ok = not bool(result)
277	            if ok and exp_out is not None:
278	                ok = out_buf.getvalue() == exp_out
279	            if ok and exp_err is not None:
280	                ok = err_buf.getvalue() == exp_err
281	            (passed if ok else failed).append(tid)
282	        except Exception:
283	            failed.append(tid)
284	    with open(results_path, "w") as f:
285	        json.dump({{"passed": passed, "failed": failed}}, f)
286	
287	_run()
288	"""
289	
290	
291	def emit_javascript(cases: list[TestCase], entrypoint: str) -> str:
292	    cases_json = json.dumps(
293	        [{"id": tc.id, "kind": tc.kind, "args": _to_json_value(tc.args),
294	          "expected": _to_json_value(tc.expected),
295	          "expectStdout": tc.expect_stdout, "expectStderr": tc.expect_stderr}
296	         for tc in cases],
297	        indent=2,
298	    )
299	    ep_json = json.dumps(entrypoint)
300	
301	    return f"""\
302	'use strict';
303	const fs = require('fs');
304	const path = require('path');
305	
306	const ENTRYPOINT = {ep_json};
307	const CASES = {cases_json};
308	
309	function deepEq(a, b) {{
310	  if (Array.isArray(a) && Array.isArray(b)) {{
311	    return a.length === b.length && a.every((x, i) => deepEq(x, b[i]));
312	  }}
313	  if (a !== null && b !== null && typeof a === 'object' && !Array.isArray(a) &&
314	      typeof b === 'object' && !Array.isArray(b)) {{
315	    const ka = Object.keys(a).sort(), kb = Object.keys(b).sort();
316	    return ka.join('\\0') === kb.join('\\0') && ka.every(k => deepEq(a[k], b[k]));
317	  }}
318	  return a === b;
319	}}
320	
321	function loadFn(sol, name) {{
322	  if (sol && typeof sol[name] === 'function') {{
323	    try {{
324	      const inst = new sol[name]();
325	      if (typeof inst[name] === 'function') return (...a) => inst[name](...a);
326	    }} catch (e) {{}}
327	    return (...a) => sol[name](...a);
328	  }}
329	  if (typeof sol === 'function') return (...a) => sol(...a);
330	  throw new Error('Cannot resolve entrypoint: ' + name);
331	}}
332	
333	function captureCall(fn, args) {{
334	  let stdout = '', stderr = '';
335	  const ow = process.stdout.write.bind(process.stdout);
336	  const ew = process.stderr.write.bind(process.stderr);
337	  process.stdout.write = c => {{ stdout += c; return true; }};
338	  process.stderr.write = c => {{ stderr += c; return true; }};
339	  let result, threw = false;
340	  try {{ result = fn(...args); }} catch (e) {{ threw = true; }}
341	  finally {{ process.stdout.write = ow; process.stderr.write = ew; }}
342	  return {{ result, stdout, stderr, threw }};
343	}}
344	
345	function run() {{
346	  const solPath = process.argv[2];
347	  const resultsPath = process.env._BCG_RESULTS_FILE;
348	  const allIds = CASES.map(c => c.id);
349	  let fn;
350	  try {{
351	    const sol = require(path.resolve(solPath));
352	    fn = loadFn(sol, ENTRYPOINT);
353	  }} catch (e) {{
354	    fs.writeFileSync(resultsPath, JSON.stringify({{passed: [], failed: allIds}}));
355	    return;
356	  }}
357	  const passed = [], failed = [];
358	  for (const c of CASES) {{
359	    try {{
360	      if (c.kind === 'raises') {{
361	        let threw = false;
362	        try {{ fn(...c.args); }} catch (e) {{ threw = true; }}
363	        (threw ? passed : failed).push(c.id);
364	        continue;
365	      }}
366	      const {{ result, stdout, stderr, threw }} = captureCall(fn, c.args);
367	      if (threw) {{ failed.push(c.id); continue; }}
368	      let ok = true;
369	      if (c.kind === 'eq') ok = deepEq(result, c.expected);
370	      else if (c.kind === 'ne') ok = !deepEq(result, c.expected);
371	      else if (c.kind === 'truthy') ok = !!result;
372	      else if (c.kind === 'falsy') ok = !result;
373	      if (ok && c.expectStdout !== null) ok = stdout === c.expectStdout;
374	      if (ok && c.expectStderr !== null) ok = stderr === c.expectStderr;
375	      (ok ? passed : failed).push(c.id);
376	    }} catch (e) {{
377	      failed.push(c.id);
378	    }}
379	  }}
380	  fs.writeFileSync(resultsPath, JSON.stringify({{passed, failed}}));
381	}}
382	
383	run();
384	"""
385	
386	
387	def emit_typescript(cases: list[TestCase], entrypoint: str) -> str:
388	    cases_json = json.dumps(
389	        [{"id": tc.id, "kind": tc.kind, "args": _to_json_value(tc.args),
390	          "expected": _to_json_value(tc.expected),
391	          "expectStdout": tc.expect_stdout, "expectStderr": tc.expect_stderr}
392	         for tc in cases],
393	        indent=2,
394	    )
395	    ep_json = json.dumps(entrypoint)
396	
397	    return f"""\
398	import * as fs from 'fs';
399	import * as path from 'path';
400	
401	const ENTRYPOINT: string = {ep_json};
402	interface Case {{
403	  id: string; kind: string; args: any[]; expected: any;
404	  expectStdout: string | null; expectStderr: string | null;
405	}}
406	const CASES: Case[] = {cases_json};
407	
408	function deepEq(a: any, b: any): boolean {{
409	  if (Array.isArray(a) && Array.isArray(b)) {{
410	    return a.length === b.length && (a as any[]).every((x: any, i: number) => deepEq(x, b[i]));
411	  }}
412	  if (a !== null && b !== null && typeof a === 'object' && !Array.isArray(a) &&
413	      typeof b === 'object' && !Array.isArray(b)) {{
414	    const ka = Object.keys(a).sort(), kb = Object.keys(b).sort();
415	    return ka.join('\\0') === kb.join('\\0') && ka.every((k: string) => deepEq(a[k], b[k]));
416	  }}
417	  return a === b;
418	}}
419	
420	function loadFn(sol: any, name: string): (...args: any[]) => any {{
421	  if (sol && typeof sol[name] === 'function') {{
422	    try {{
423	      const inst: any = new sol[name]();
424	      if (typeof inst[name] === 'function') return (...a: any[]) => inst[name](...a);
425	    }} catch (e) {{}}
426	    return (...a: any[]) => sol[name](...a);
427	  }}
428	  if (typeof sol === 'function') return (...a: any[]) => sol(...a);
429	  throw new Error('Cannot resolve entrypoint: ' + name);
430	}}
431	
432	function captureCall(
433	  fn: (...a: any[]) => any, args: any[]
434	): {{ result: any; stdout: string; stderr: string; threw: boolean }} {{
435	  let stdout = '', stderr = '';
436	  const ow = process.stdout.write.bind(process.stdout);
437	  const ew = process.stderr.write.bind(process.stderr);
438	  (process.stdout as any).write = (c: any) => {{ stdout += c; return true; }};
439	  (process.stderr as any).write = (c: any) => {{ stderr += c; return true; }};
440	  let result: any, threw = false;
441	  try {{ result = fn(...args); }} catch (e) {{ threw = true; }}
442	  finally {{ process.stdout.write = ow; process.stderr.write = ew; }}
443	  return {{ result, stdout, stderr, threw }};
444	}}
445	
446	function run(): void {{
447	  const solPath: string = process.argv[2];
448	  const resultsPath: string = process.env['_BCG_RESULTS_FILE']!;
449	  const allIds: string[] = CASES.map((c: Case) => c.id);
450	  let fn: (...a: any[]) => any;
451	  try {{
452	    // eslint-disable-next-line @typescript-eslint/no-var-requires
453	    const sol = require(path.resolve(solPath));
454	    fn = loadFn(sol, ENTRYPOINT);
455	  }} catch (e) {{
456	    fs.writeFileSync(resultsPath, JSON.stringify({{passed: [], failed: allIds}}));
457	    return;
458	  }}
459	  const passed: string[] = [], failed: string[] = [];
460	  for (const c of CASES) {{
461	    try {{
462	      if (c.kind === 'raises') {{
463	        let threw = false;
464	        try {{ fn(...c.args); }} catch (e) {{ threw = true; }}
465	        (threw ? passed : failed).push(c.id);
466	        continue;
467	      }}
468	      const {{ result, stdout, stderr, threw }} = captureCall(fn, c.args);
469	      if (threw) {{ failed.push(c.id); continue; }}
470	      let ok = true;
471	      if (c.kind === 'eq') ok = deepEq(result, c.expected);
472	      else if (c.kind === 'ne') ok = !deepEq(result, c.expected);
473	      else if (c.kind === 'truthy') ok = !!result;
474	      else if (c.kind === 'falsy') ok = !result;
475	      if (ok && c.expectStdout !== null) ok = stdout === c.expectStdout;
476	      if (ok && c.expectStderr !== null) ok = stderr === c.expectStderr;
477	      (ok ? passed : failed).push(c.id);
478	    }} catch (e) {{
479	      failed.push(c.id);
480	    }}
481	  }}
482	  fs.writeFileSync(resultsPath, JSON.stringify({{passed, failed}}));
483	}}
484	
485	run();
486	"""
487	
488	
489	# ---------------------------------------------------------------------------
490	# generate command
491	# ---------------------------------------------------------------------------
492	
493	_TESTER_NAMES = {
494	    "python": "tester.py",
495	    "javascript": "tester.js",
496	    "typescript": "tester.ts",
497	}
498	
499	_EMITTERS = {
500	    "python": emit_python,
501	    "javascript": emit_javascript,
502	    "typescript": emit_typescript,
503	}
504	
505	
506	def cmd_generate(args: argparse.Namespace) -> int:
507	    tests_dir = Path(args.tests_dir)
508	    tests_py = tests_dir / "tests.py"
509	    if not tests_py.exists():
510	        print(f"error: {tests_py} not found", file=sys.stderr)
511	        return 1
512	
513	    try:
514	        source = tests_py.read_text()
515	        cases = parse_tests(source, args.entrypoint)
516	    except Exception as e:
517	        print(f"error: failed to parse tests.py: {e}", file=sys.stderr)
518	        return 1
519	
520	    code = _EMITTERS[args.lang](cases, args.entrypoint)
521	    tester_path = tests_dir / _TESTER_NAMES[args.lang]
522	    tmp_path = tester_path.with_suffix(tester_path.suffix + ".tmp")
523	    try:
524	        tmp_path.write_text(code)
525	        tmp_path.replace(tester_path)
526	    except Exception as e:
527	        tmp_path.unlink(missing_ok=True)
528	        print(f"error: failed to write tester: {e}", file=sys.stderr)
529	        return 1
530	    return 0
531	
532	
533	# ---------------------------------------------------------------------------
534	# test command
535	# ---------------------------------------------------------------------------
536	
537	_ERROR_RESULT = json.dumps({"status": "error", "passed": [], "failed": []})
538	
539	_SUBPROC = {
540	    "python": lambda tester, sol: [sys.executable, str(tester), str(sol)],
541	    "javascript": lambda tester, sol: ["node", str(tester), str(sol)],
542	    "typescript": lambda tester, sol: ["npx", "tsx", str(tester), str(sol)],
543	}
544	
545	
546	def _error_exit() -> int:
547	    print(_ERROR_RESULT)
548	    return 2
549	
550	
551	def cmd_test(args: argparse.Namespace) -> int:
552	    if args.lang not in _TESTER_NAMES:
553	        return _error_exit()
554	
555	    tests_dir = Path(args.tests_dir)
556	    tester_path = tests_dir / _TESTER_NAMES[args.lang]
557	    if not tester_path.exists():
558	        return _error_exit()
559	
560	    sol_path = Path(args.solution_path)
561	    fd, results_file = tempfile.mkstemp(suffix=".json")
562	    os.close(fd)
563	    try:
564	        cmd = _SUBPROC[args.lang](tester_path, sol_path)
565	        env = {**os.environ, "_BCG_RESULTS_FILE": results_file}
566	        try:
